import re
md = params.get('markdown') or params.get('text') or params.get('input') or ''
if not isinstance(md, str) or not md.strip():
    result = {'error': 'pass params.markdown'}
else:
    # Strip fenced code blocks so we don't pick up '# comments' inside code.
    no_fence = re.sub(r'```[\s\S]*?```', '', md, flags=re.MULTILINE)
    heading_re = re.compile(r'^(#{1,6})\s+(.+?)\s*$', re.MULTILINE)
    seen = {}
    lines = []
    count = 0
    for m in heading_re.finditer(no_fence):
        level = len(m.group(1))
        title = m.group(2).strip()
        # GitHub-style anchor: lower, replace non-word with dash, dedupe.
        anchor = re.sub(r'[^\w\u4e00-\u9fff\u3040-\u30ff -]', '', title.lower()).strip().replace(' ', '-')
        anchor = re.sub(r'-+', '-', anchor) or 'heading'
        if anchor in seen:
            seen[anchor] += 1
            anchor = f'{anchor}-{seen[anchor]}'
        else:
            seen[anchor] = 0
        indent = '  ' * (level - 1)
        lines.append(f'{indent}- [{title}](#{anchor})')
        count += 1
    result = {'toc': '\n'.join(lines), 'heading_count': count}
